<script setup lang="ts">
import { computed, ref } from 'vue'
import type { KnowledgePoint, ResourceItem } from '../domain/types'
import { formatBytes, resourceLabel, validResourceUrl } from '../domain/resources'
import { errorText, invoke } from '../desktop'
import Icon from './Icon.vue'
import ModalShell from './ModalShell.vue'
const props = defineProps<{ resources: ResourceItem[]; points: KnowledgePoint[]; busy: boolean; enabled: boolean; operationError?: string; run: (command: string, args?: Record<string, unknown>, message?: string) => Promise<boolean> }>()
const emit = defineEmits<{ preview: [resource: ResourceItem]; import: [resource: ResourceItem]; locate: [id: string]; error: [message: string] }>()
const query = ref('')
const filter = ref('all')
const showAdd = ref(false)
const mode = ref<'file' | 'link'>('file')
const path = ref('')
const title = ref('')
const url = ref('')
const selectedPoints = ref<string[]>([])
const pointQuery = ref('')
const localError = ref('')
const copying = ref(false)
const jobId = ref('')
const associating = ref<ResourceItem | null>(null)
const removing = ref<ResourceItem | null>(null)
const filtered = computed(() => props.resources.filter(r => (filter.value === 'all' || r.kind === filter.value) && `${r.title}\n${r.filename ?? ''}`.toLowerCase().includes(query.value.trim().toLowerCase())))
const kinds = computed(() => [...new Set(props.resources.map(r => r.kind))])
const filteredPoints = computed(() => props.points.filter(p => p.name.toLowerCase().includes(pointQuery.value.trim().toLowerCase())))
function linked(id: string) { return props.points.filter(p => p.resourceIds.includes(id)) }
function openAdd() { mode.value = 'file'; path.value = ''; title.value = ''; url.value = ''; selectedPoints.value = []; pointQuery.value = ''; localError.value = ''; showAdd.value = true }
async function chooseFile() { try { const picked = await invoke<string | null>('choose_file'); if (picked) { path.value = picked; if (!title.value) title.value = picked.split(/[\\/]/).at(-1) ?? '' } } catch (e) { localError.value = errorText(e) } }
async function save() {
  localError.value = ''
  if (mode.value === 'file' && !path.value.trim()) { localError.value = '请选择一个本机文件。'; return }
  if (mode.value === 'link' && (!title.value.trim() || !validResourceUrl(url.value))) { localError.value = '请输入资料名称和有效的 http:// 或 https:// 地址。'; return }
  let success = false
  if (mode.value === 'file') {
    jobId.value = crypto.randomUUID(); copying.value = true
    success = await props.run('resource_add_file', { path: path.value.trim(), title: title.value.trim(), pointIds: [...selectedPoints.value], jobId: jobId.value }, '资料副本与记录已保存到本机')
    copying.value = false
  } else success = await props.run('resource_add_link', { title: title.value.trim(), url: url.value.trim(), pointIds: [...selectedPoints.value] }, '链接资料已保存到本机')
  if (success) { showAdd.value = false; query.value = ''; filter.value = 'all' }
  else localError.value = '资料未保存成功。请查看页面错误信息，修正后重试。'
}
async function cancelCopy() { try { await invoke('copy_cancel', { jobId: jobId.value }) } catch (e) { localError.value = errorText(e) } }
function beginAssociation(resource: ResourceItem) { associating.value = resource; selectedPoints.value = linked(resource.id).map(p => p.id); pointQuery.value = ''; localError.value = '' }
async function saveAssociation() { if (associating.value && await props.run('resource_associate', { id: associating.value.id, pointIds: [...selectedPoints.value] }, '资料关联已保存')) associating.value = null }
async function remove() { if (removing.value && await props.run('resource_remove', { id: removing.value.id }, '资料已移除，知识点已保留')) removing.value = null }
</script>
<template>
  <section class="resource-library-page glass-panel" aria-label="资料库">
    <header class="library-heading"><div><h1>资料库 <span>{{ resources.length }}</span></h1><p>保存本地文件副本或网页链接，关联并复用学习来源。</p></div><button class="button button-primary" :disabled="busy || !enabled" @click="openAdd"><Icon name="plus" :size="17" />添加资料</button></header>
    <div class="library-toolbar"><label class="library-search"><Icon name="search" :size="17" /><input v-model="query" aria-label="搜索资料" placeholder="搜索名称或文件名" /></label><select v-model="filter" class="field" aria-label="资料类型"><option value="all">全部类型</option><option v-for="kind in kinds" :key="kind" :value="kind">{{ resourceLabel(kind) }}</option></select><span>{{ filtered.length }} 份资料</span></div>
    <div class="library-list"><article v-for="resource in filtered" :key="resource.id" class="library-row" :aria-label="'学习资料：' + resource.title"><div class="library-resource"><Icon :name="resource.kind === 'link' ? 'external' : 'file'" :size="26" /><div><h2>{{ resource.title }}</h2><p class="library-meta">{{ resourceLabel(resource.kind) }} <span v-if="resource.size !== undefined">{{ formatBytes(resource.size) }}</span> <span :class="{ missing: resource.status === 'missing' }">{{ resource.status === 'missing' ? '文件缺失' : '就绪' }}</span></p><p v-if="resource.filename" class="library-meta">{{ resource.filename }}</p><p v-if="resource.url" class="library-url">{{ resource.url }}</p></div></div><div class="library-associations"><button v-for="point in linked(resource.id)" :key="point.id" class="tag" @click="emit('locate', point.id)">{{ point.name }}</button><span v-if="!linked(resource.id).length" class="muted">尚未关联知识点</span></div><div class="library-actions"><button class="button" @click="emit('preview', resource)">{{ resource.kind === 'link' ? '查看链接' : '查看资料' }}</button><button class="button" :disabled="busy" @click="beginAssociation(resource)">关联知识点</button><button class="text-button" @click="emit('import', resource)">导入知识</button><button class="text-button" :disabled="busy" @click="removing = resource">移除资料</button></div></article><div v-if="!filtered.length" class="library-empty"><Icon name="book" :size="32" /><h2>{{ resources.length ? '未找到匹配资料' : '添加第一份学习资料' }}</h2><p>{{ resources.length ? '换一个关键词或切换类型。' : '文件会复制到当前数据目录，原文件移动后仍可使用。' }}</p></div></div>
    <footer class="library-page-footer">只有文件副本完整保存、正式记录提交后，资料才会显示就绪。知识点删除不会删除资料。</footer>
  </section>
  <ModalShell v-if="showAdd" title="添加学习资料" wide @close="!busy && (showAdd = false)"><form class="resource-add-form" @submit.prevent="save"><div class="resource-form-main"><div class="resource-mode"><button type="button" :disabled="busy" :class="{ selected: mode === 'file' }" @click="mode = 'file'">本地文件</button><button type="button" :disabled="busy" :class="{ selected: mode === 'link' }" @click="mode = 'link'">网页链接</button></div><template v-if="mode === 'file'"><label for="resource-path">本机文件</label><div class="file-path-row"><input id="resource-path" v-model="path" class="field" aria-label="资料文件路径" :disabled="busy" placeholder="选择文件或填写完整路径" /><button type="button" class="button" :disabled="busy" @click="chooseFile">选择文件</button></div><p class="resource-form-help">文件会保存为本机副本，支持大文件。请确保数据目录有足够可用空间。</p></template><label for="resource-title">资料名称{{ mode === 'file' ? '（可选，默认文件名）' : '' }}</label><input id="resource-title" v-model="title" class="field" aria-label="资料名称" :disabled="busy" /><template v-if="mode === 'link'"><label for="resource-url">网页地址</label><input id="resource-url" v-model="url" class="field" aria-label="网页地址" :disabled="busy" placeholder="https://…" /></template><p v-if="localError || operationError" role="alert" class="resource-errors">{{ operationError || localError }}</p><p v-if="copying" role="status">正在复制并保存，完成后才能打开。<button type="button" class="button" @click="cancelCopy">取消复制</button></p></div><fieldset class="resource-points"><legend>关联已有知识点（可选）</legend><input v-model="pointQuery" class="field" aria-label="查找要关联的知识点" placeholder="查找知识点" :disabled="busy" /><div class="resource-point-list"><label v-for="point in filteredPoints" :key="point.id"><input v-model="selectedPoints" type="checkbox" :value="point.id" :disabled="busy" :aria-label="'关联知识点 ' + point.name" /><span>{{ point.name }}<small>{{ point.isTheme ? '主题' : '知识点' }}</small></span></label><p v-if="!points.length">还没有知识点，可稍后关联。</p></div></fieldset><footer class="resource-form-footer"><button type="button" class="button" :disabled="busy" @click="showAdd = false">取消</button><button class="button button-primary" :disabled="busy" type="submit">{{ busy ? '正在保存…' : '保存资料' }}</button></footer></form></ModalShell>
  <ModalShell v-if="associating" title="关联知识点" @close="!busy && (associating = null)"><form @submit.prevent="saveAssociation"><p>{{ associating.title }}</p><p class="resource-form-help">勾选建立关联；取消勾选只移除关联，资料仍保留。</p><input v-model="pointQuery" class="field" aria-label="查找要关联的知识点" placeholder="查找知识点" /><div class="resource-point-list"><label v-for="point in filteredPoints" :key="point.id"><input v-model="selectedPoints" type="checkbox" :value="point.id" :disabled="busy" :aria-label="'关联知识点 ' + point.name" /><span>{{ point.name }}</span></label></div><footer class="resource-form-footer"><button type="button" class="button" :disabled="busy" @click="associating = null">取消</button><button type="submit" class="button button-primary" :disabled="busy">保存关联（{{ selectedPoints.length }}）</button></footer></form></ModalShell>
  <ModalShell v-if="removing" title="移除资料" @close="!busy && (removing = null)"><p class="resource-form-help">移除“{{ removing.title }}”并解除与 {{ linked(removing.id).length }} 个知识点的关联。知识点和其他资料保留。此操作无法撤销。</p><footer class="resource-form-footer"><button class="button" :disabled="busy" @click="removing = null">取消</button><button class="button button-primary" :disabled="busy" @click="remove">确认移除资料</button></footer></ModalShell>
</template>
<style scoped>
.resource-library-page { margin: 8px 16px 16px; min-height: 0; display: flex; flex-direction: column; overflow: hidden; padding: 28px 32px 0; }.library-heading { display: flex; justify-content: space-between; align-items: center; gap: 24px; padding-bottom: 26px; }.library-heading h1 { font-size: 28px; font-weight: 650; }.library-heading h1 span { font-size: 15px; color: #777; margin-left: 8px; }.library-heading p { color: #646464; margin-top: 10px; font-size: 13px; }.library-toolbar { display: flex; gap: 12px; align-items: center; padding: 16px 0; border-top: 1px solid #dedede; font-size: 12px; color: #777; }.library-search { display: flex; gap: 9px; align-items: center; width: min(480px,55%); padding: 0 12px; height: 39px; background: #fff9; border: 1px solid #d1d1d1; border-radius: 8px; }.library-search input { flex: 1; min-width: 0; background: transparent; border: 0; font-size: 13px; }.library-list { min-height: 0; flex: 1; overflow: auto; }.library-row { display: grid; grid-template-columns: minmax(200px,1.2fr) minmax(130px,1fr) 290px; gap: 22px; align-items: center; padding: 22px 8px; border-bottom: 1px solid #dedede; }.library-resource { display: flex; align-items: flex-start; gap: 14px; min-width: 0; }.library-resource>svg { flex-shrink: 0; }.library-resource h2 { font-size: 15px; line-height: 1.55; overflow-wrap: anywhere; }.library-meta,.library-url { color: #747474; font-size: 11px; margin-top: 7px; overflow-wrap: anywhere; }.library-meta span { margin-left: 7px; }.missing { color: #9b3f31; }.library-associations { display: flex; flex-wrap: wrap; gap: 6px; font-size: 12px; }.library-actions { display: flex; gap: 8px; justify-content: flex-end; flex-wrap: wrap; }.library-actions .button,.library-actions .text-button { font-size: 12px; }.library-empty { display: flex; flex-direction: column; align-items: center; text-align: center; padding: 75px 20px; gap: 18px; color: #777; }.library-empty h2 { font-size: 18px; color: #444; }.library-page-footer { padding: 15px 0; color: #777; font-size: 12px; line-height: 1.7; }.resource-add-form { display: grid; grid-template-columns: minmax(0,1.4fr) minmax(210px,1fr); gap: 24px; }.resource-form-main { min-width: 0; }.resource-form-main>label { display: block; font-size: 13px; margin: 16px 0 8px; }.resource-form-main>.field { width: 100%; box-sizing: border-box; }.resource-mode { display: flex; gap: 4px; padding: 4px; background: #e9e9e9; border-radius: 9px; margin-bottom: 18px; }.resource-mode button { flex: 1; padding: 8px; border-radius: 6px; font-size: 13px; }.resource-mode .selected { background: #fff; }.file-path-row { display: flex; gap: 8px; margin-top: 8px; }.file-path-row input { flex: 1; min-width: 0; }.resource-form-help { color: #646464; font-size: 12px; line-height: 1.8; margin: 14px 0; }.resource-points { border: 0; padding: 0; min-width: 0; margin: 0; }.resource-points legend { font-size: 14px; font-weight: 600; margin-bottom: 12px; }.resource-point-list { display: flex; flex-direction: column; gap: 6px; max-height: 310px; overflow: auto; margin: 12px 0 20px; }.resource-point-list>label { display: flex; gap: 10px; align-items: flex-start; padding: 10px; border: 1px solid #d9d9d9; border-radius: 8px; background: #ffffff9c; cursor: pointer; font-size: 13px; }.resource-point-list small { display: block; color: #777; font-size: 10px; }.resource-point-list>p { color: #777; font-size: 12px; padding: 15px; }.resource-form-footer { grid-column: 1/-1; display: flex; justify-content: flex-end; gap: 10px; padding-top: 18px; border-top: 1px solid #d9d9d9; }.resource-errors { padding: 12px; margin: 16px 0; border: 1px solid #b4837c; border-radius: 8px; background: #fff4f0; font-size: 13px; line-height: 1.8; }@media(max-width:1100px){.resource-library-page { padding: 24px 20px 0; }.library-row { grid-template-columns: minmax(200px,1fr) 260px; }.library-associations { grid-column: 1; }.library-actions { grid-column: 2; grid-row: 1/3; }}@media(max-width:750px){.resource-add-form { grid-template-columns: 1fr; }.library-row { grid-template-columns: 1fr; }.library-actions { grid-column: auto; grid-row: auto; justify-content: flex-start; }}
</style>
